import pandas as pd
import numpy as np

# Load the data
crime_data = pd.read_csv('chunks_csv/getisord/getisord_crime_first_half_2021.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Handle missing values by replacing them with the mean imputation method
crime_data['crime_rate_value'] = crime_data['crime_rate_value'].fillna(crime_data['crime_rate_value'].mean())

# Define neighborhoods
neighborhoods = {}
for index, row in adjacency_data.iterrows():
    if row['borough'] not in neighborhoods:
        neighborhoods[row['borough']] = [row['neighbor']]
    else:
        neighborhoods[row['borough']].append(row['neighbor'])

# Calculate combined crime rates
combined_crime_rates = {}
for borough, neighbors in neighborhoods.items():
    combined_crime_rate = crime_data.loc[crime_data['borough'] == borough, 'crime_rate_value'].values[0]
    for neighbor in neighbors:
        combined_crime_rate += crime_data.loc[crime_data['borough'] == neighbor, 'crime_rate_value'].values[0]
    combined_crime_rates[borough] = combined_crime_rate

# Calculate z-scores
citywide_average = crime_data['crime_rate_value'].mean()
citywide_std = crime_data['crime_rate_value'].std()
z_scores = {}
for borough, crime_rate in combined_crime_rates.items():
    z_score = (crime_rate - citywide_average) / citywide_std
    z_scores[borough] = z_score

# Identify hot and cold spots
hot_cold_spots = {}
for borough, z_score in z_scores.items():
    if abs(z_score) > 1.96:  # 95% confidence interval
        hot_cold_spots[borough] = 'HOT' if z_score > 0 else 'COLD'

# Print results
data_points_used = len(hot_cold_spots)
print(f"data_points_used = {data_points_used}")
results = []
for borough, hot_cold in hot_cold_spots.items():
    results.append(f"{borough} ({hot_cold}, Gi*={z_scores[borough]})")
print(f"FINAL ANSWER: {', '.join(results)}")
